 const meteors=state.meteors;for(let i=0;i<4;i++){const d=meteors.drops[i],marker=rig.markers[i],sprite=rig.meteors[i],impact=rig.impacts[i];marker.visible=sprite.visible=impact.visible=false;if(!meteors.active||i>=meteors.count||!d.valid)continue;const warning=meteors.age-(d.delay-.6);if(!d.done&&warning>=0)place(marker,d.x,d.y,170,0,.5+.25*Math.min(1,warning/.6));const flight=(meteors.age-(d.delay-.3))/.3;if(!d.done&&flight>=0&&flight<=1)place(sprite,d.x,d.y-(1-flight)*110,82+flight*12,0,.85+flight*.15);if(d.life>0){const p=1-d.life/.45;place(impact,d.x,d.y,170*(.55+.45*p),0,Math.min(1,d.life/.45*1.5))}}
